correction.text:
{
  "corrected": "I am Karthik and I have two years of sales experience.",
  "mistakes": [
    {
      "wrong": "Myself Karthik",
      "right": "I am Karthik",
      "type": "grammar",
      "explanation_tamil": "நான் என்பதற்கு 'மெய்ம்' பயன்படுத்தக்கூடாது."
    },
    {
      "wrong": "having",
      "right": "have",
      "type": "grammar",
      "explanation_tamil": "பெயர்ச்சொல்லுக்கு 'having' பயன்படுத்தக்கூடாது."
    },
    {
      "wrong": "in sales",
      "right": "sales",
      "type": "style",
      "explanation_tamil": "இது தொழில்நுட்பத் துறையில் பயன்படுத்தப்படும் துல்லியமான வார்த்தை."
    }
  ]
}

{
  "corrected": "I have been working at this company since 2019.",
  "mistakes": [
    {
      "wrong": "working",
      "right": "have been working",
      "type": "grammar",
      "explanation_tamil": "இந்தச் சொல்லுக்கு 'have been working' என்று மாற்ற வேண்டும்."
    },
    {
      "wrong": "in",
      "right": "at",
      "type": "style",
      "explanation_tamil": "நிறுவனத்தில் பணிபுரியும்போது 'at' என்று பயன்படுத்த வேண்டும்."
    }
  ]
}

{
  "corrected": "Please revert to me today.",
  "mistakes": [
    {
      "wrong": "revert back",
      "right": "revert",
      "type": "style",
      "explanation_tamil": "பிரிவுக்குத் திரும்புவதற்கு 'revert back' என்று சொல்லக்கூடாது; 'revert' போதுமானது."
    }
  ]
}

{
  "corrected": "We discussed the budget and he said it was fine.",
  "mistakes": [
    {
      "wrong": "discussed about",
      "right": "discussed",
      "type": "grammar",
      "explanation_tamil": "படிப்படியாகப் பேசுவதற்கு 'discussed about' என்று சொல்ல முடியாது; 'discussed' போதும்."
    },
    {
      "wrong": "told that",
      "right": "said",
      "type": "grammar",
      "explanation_tamil": "'told that' என்பதற்குப் பதிலாக 'said' என்று சொல்ல வேண்டும்."
    },
    {
      "wrong": "it is",
      "right": "it was",
      "type": "grammar",
      "explanation_tamil": "முன்னர் நடந்த விஷயத்தைக் குறிப்பிட 'was' என்று பயன்படுத்த வேண்டும்."
    },
    {
      "wrong": "discussed about",
      "right": "discussed",
      "type": "style",
      "explanation_tamil": "பொருளாதாரத் திட்டத்தைப் பற்றி பேசியது என்று தெளிவாகச் சொல்ல 'discussed the budget' என்று பயன்படுத்தலாம்."
    }
  ]
}

{
  "corrected": "Please take the necessary action and send the files.",
  "mistakes": [
    {
      "wrong": "Kindly do the needful",
      "right": "Please take the necessary action",
      "type": "style",
      "explanation_tamil": "இந்த வார்த்தைகள் தொழில்முறைத் தமிழில் பயன்படுத்தப்படாது."
    }
  ]
}

{
  "corrected": "What is your full name?",
  "mistakes": [
    {
      "wrong": "good name",
      "right": "full name",
      "type": "style",
      "explanation_tamil": "பொருளாதாரத் துறையில் 'good name' என்பது சரியான சொல்லாடல் அல்ல."
    }
  ]
}

{
  "corrected": "I have been working here for three years and I enjoy my role.",
  "mistakes": []
}

{
  "corrected": "Could you please send me the updated report by Friday?",
  "mistakes": []
}
